    m[0] = true
    for i := 0; i < t; i++ {
        m[a-(da*i)] = true
    }
    ans := false
    for i := 0; i <= t; i++ {
        if i == t {
            if m[x] {
                ans = true
                break
            }
        } else if m[x-(b-(db*i))] {
            ans = true
            break
        }
    }
    if ans { fmt.Println("YES") } else { fmt.Println("NO") }
}
